ithub.com/najirh/netflix_sql_project/raw/refs/heads/main/Solutions%20of%2015%20business%20problems.sql","renderImageOrRaw":false,"shortPath":null,"symbolsEnabled":true,"tabSize":4,"topBannersInfo":{"overridingGlobalFundingFile":false,"globalPreferredFundingPath":null,"showInvalidCitationWarning":false,"citationHelpUrl":"https://docs.github.com/github/creating-cloning-and-archiving-repositories/creating-a-repository-on-github/about-citation-files","actionsOnboardingTip":null},"truncated":false,"viewable":true,"workflowRedirectUrl":null},"copilotInfo":{"documentationUrl":"https://docs.github.com/copilot/overview-of-github-copilot/about-github-copilot-for-individuals","notices":{"codeViewPopover":{"dismissed":false,"dismissPath":"/settings/dismiss-notice/code_view_copilot_popover"}},"userAccess":{"hasSubscriptionEnded":false,"orgHasCFBAccess":false,"userHasCFIAccess":false,"userHasOrgs":false,"userIsOrgAdmin":false,"userIsOrgMember":false,"business":null,"featureRequestInfo":null}},"copilotAccessAllowed":false,"copilotSpacesEnabled":false,"modelsAccessAllowed":false,"modelsRepoIntegrationEnabled":false,"isMarketplaceEnabled":true},"codeViewBlobLayoutRoute.StyledBlob":{"rawLines":["-- Netflix Data Analysis using SQL","-- Solutions of 15 business problems","-- 1. Count the number of Movies vs TV Shows","","SELECT ","\ttype,","\tCOUNT(*)","FROM netflix","GROUP BY 1","","-- 2. Find the most common rating for movies and TV shows","","WITH RatingCounts AS (","    SELECT ","        type,","        rating,","        COUNT(*) AS rating_count","    FROM netflix","    GROUP BY type, rating","),","RankedRatings AS (","    SELECT ","        type,","        rating,","        rating_count,","        RANK() OVER (PARTITION BY type ORDER BY rating_count DESC) AS rank","    FROM RatingCounts",")","SELECT ","    type,","    rating AS most_frequent_rating","FROM RankedRatings","WHERE rank = 1;","","","-- 3. List all movies released in a specific year (e.g., 2020)","","SELECT * ","FROM netflix","WHERE release_year = 2020","","","-- 4. Find the top 5 countries with the most content on Netflix","","SELECT * ","FROM","(","\tSELECT ","\t\t-- country,","\t\tUNNEST(STRING_TO_ARRAY(country, ',')) as country,","\t\tCOUNT(*) as total_content","\tFROM netflix","\tGROUP BY 1",")as t1","WHERE country IS NOT NULL","ORDER BY total_content DESC","LIMIT 5","","","-- 5. Identify the longest movie","","SELECT ","\t*","FROM netflix","WHERE type = 'Movie'","ORDER BY SPLIT_PART(duration, ' ', 1)::INT DESC","","","-- 6. Find content added in the last 5 years","SELECT","*","FROM netflix","WHERE TO_DATE(date_added, 'Month DD, YYYY') \u003e= CURRENT_DATE - INTERVAL '5 years'","","","-- 7. Find all the movies/TV shows by director 'Rajiv Chilaka'!","","SELECT *","FROM","(","","SELECT ","\t*,","\tUNNEST(STRING_TO_ARRAY(director, ',')) as director_name","FROM ","netflix",")","WHERE ","\tdirector_name = 'Rajiv Chilaka'","","","","-- 8. List all TV shows with more than 5 seasons","","SELECT *","FROM netflix","WHERE ","\tTYPE = 'TV Show'","\tAND","\tSPLIT_PART(duration, ' ', 1)::INT \u003e 5","","","-- 9. Count the number of content items in each genre","","SELECT ","\tUNNEST(STRING_TO_ARRAY(listed_in, ',')) as genre,","\tCOUNT(*) as total_content","FROM netflix","GROUP BY 1","","","-- 10. Find each year and the average numbers of content release by India on netflix. ","-- return top 5 year with highest avg content release !","","","SELECT ","\tcountry,","\trelease_year,","\tCOUNT(show_id) as total_release,","\tROUND(","\t\tCOUNT(show_id)::numeric/","\t\t\t\t\t\t\t\t(SELECT COUNT(show_id) FROM netflix WHERE country = 'India')::numeric * 100 ","\t\t,2","\t\t)","\t\tas avg_release","FROM netflix","WHERE country = 'India' ","GROUP BY country, 2","ORDER BY avg_release DESC ","LIMIT 5","","","-- 11. List all movies that are documentaries","SELECT * FROM netflix","WHERE listed_in LIKE '%Documentaries'","","","","-- 12. Find all content without a director","SELECT * FROM netflix","WHERE director IS NULL","","","-- 13. Find how many movies actor 'Salman Khan' appeared in last 10 years!","","SELECT * FROM netflix","WHERE ","\tcasts LIKE '%Salman Khan%'","\tAND ","\trelease_year \u003e EXTRACT(YEAR FROM CURRENT_DATE) - 10","","","-- 14. Find the top 10 actors who have appeared in the highest number of movies produced in India.","","","","SELECT ","\tUNNEST(STRING_TO_ARRAY(casts, ',')) as actor,","\tCOUNT(*)","FROM netflix","WHERE country = 'India'","GROUP BY 1","ORDER BY 2 DESC","LIMIT 10","","/*","Question 15:","Categorize the content based on the presence of the keywords 'kill' and 'violence' in ","the description field. Label content containing these keywords as 'Bad' and all other ","content as 'Good'. Count how many items fall into each category.","*/","","","SELECT ","    category,","\tTYPE,","    COUNT(*) AS content_count","FROM (","    SELECT ","\t\t*,","        CASE ","            WHEN description ILIKE '%kill%' OR description ILIKE '%violence%' THEN 'Bad'","            ELSE 'Good'","        END AS category","    FROM netflix",") AS categorized_content","GROUP BY 1,2","ORDER BY 2","","","","","-- End of reports"],"stylingDirectives":null,"colorizedLines":["\u003cspan class=\"pl-c\"\u003e\u003cspan class=\"pl-c\"\u003e--\u003c/span\u003e Netflix Data Analysis using SQL\u003c/span\u003e","\u003cspan class=\"pl-c\"\u003e\u003cspan class=\"pl-c\"\u003e--\u003c/span\u003e Solutions of 15 business problems\u003c/span\u003e","\u003cspan class=\"pl-c\"\u003e\u003cspan class=\"pl-c\"\u003e--\u003c/span\u003e 1. Count the number of Movies vs TV Shows\u003c/span\u003e","","\u003cspan class=\"pl-k\"\u003eSELECT\u003c/span\u003e ","\ttype,","\t\u003cspan class=\"pl-c1\"\u003eCOUNT\u003c/span\u003e(\u003cspan class=\"pl-k\"\u003e*\u003c/span\u003e)","\u003cspan class=\"pl-k\"\u003eFROM\u003c/span\u003e netflix","\u003cspan class=\"pl-k\"\u003eGROUP BY\u003c/span\u003e \u003cspan class=\"pl-c1\"\u003e1\u003c/span\u003e","","\u003cspan class=\"pl-c\"\u003e\u003cspan class=\"pl-c\"\u003e--\u003c/span\u003e 2. Find the most common rating for movies and TV shows\u003c/span\u003e","","WITH RatingCounts \u003cspan class=\"pl-k\"\u003eAS\u003c/span\u003e (","    \u003cspan class=\"pl-k\"\u003eSELECT\u003c/span\u003e ","        type,","        rating,","        \u003cspan class=\"pl-c1\"\u003eCOUNT\u003c/span\u003e(\u003cspan class=\"pl-k\"\u003e*\u003c/span\u003e) \u003cspan class=\"pl-k\"\u003eAS\u003c/span\u003e rating_count","    \u003cspan class=\"pl-k\"\u003eFROM\u003c/span\u003e netflix","    \u003cspan class=\"pl-k\"\u003eGROUP BY\u003c/span\u003e type, rating","),","RankedRatings \u003cspan class=\"pl-k\"\u003eAS\u003c/span\u003e (","    \u003cspan class=\"pl-k\"\u003eSELECT\u003c/span\u003e ","        type,","        rating,","        rating_count,","        RANK() OVER (PARTITION BY type \u003cspan class=\"pl-k\"\u003eORDER BY\u003c/span\u003e rating_count \u003cspan class=\"pl-k\"\u003eDESC\u003c/span\u003e) \u003cspan class=\"pl-k\"\u003eAS\u003c/span\u003e rank","    \u003cspan class=\"pl-k\"\u003eFROM\u003c/span\u003e RatingCounts",")","\u003cspan class=\"pl-k\"\u003eSELECT\u003c/span\u003e ","    type,","    rating \u003cspan class=\"pl-k\"\u003eAS\u003c/span\u003e most_frequent_rating","\u003cspan class=\"pl-k\"\u003eFROM\u003c/span\u003e RankedRatings","\u003cspan class=\"pl-k\"\u003eWHERE\u003c/span\u003e rank \u003cspan class=\"pl-k\"\u003e=\u003c/span\u003e \u003cspan class=\"pl-c1\"\u003e1\u003c/span\u003e;","","","\u003cspan class=\"pl-c\"\u003e\u003cspan class=\"pl-c\"\u003e--\u003c/span\u003e 3. List all movies released in a specific year (e.g., 2020)\u003c/span\u003e","","\u003cspan class=\"pl-k\"\u003eSELECT\u003c/span\u003e \u003cspan class=\"pl-k\"\u003e*\u003c/span\u003e ","\u003cspan class=\"pl-k\"\u003eFROM\u003c/span\u003e netflix","\u003cspan class=\"pl-k\"\u003eWHERE\u003c/span\u003e release_year \u003cspan class=\"pl-k\"\u003e=\u003c/span\u003e \u003cspan class=\"pl-c1\"\u003e2020\u003c/span