g-right:16px">180</div></div><div class="CodeLinesSSRNoVirtualization-module__reactNoVirtualizationWrapperLinesSsr__f1Qyj"><div data-line-number="181" class="react-line-number react-code-text" style="padding-right:16px">181</div><div data-line-number="182" class="react-line-number react-code-text" style="padding-right:16px">182</div><div data-line-number="183" class="react-line-number react-code-text" style="padding-right:16px">183</div><div data-line-number="184" class="react-line-number react-code-text" style="padding-right:16px">184</div><div data-line-number="185" class="react-line-number react-code-text" style="padding-right:16px">185</div><div data-line-number="186" class="react-line-number react-code-text" style="padding-right:16px">186</div><div data-line-number="187" class="react-line-number react-code-text" style="padding-right:16px">187</div><div data-line-number="188" class="react-line-number react-code-text" style="padding-right:16px">188</div><div data-line-number="189" class="react-line-number react-code-text" style="padding-right:16px">189</div><div data-line-number="190" class="react-line-number react-code-text" style="padding-right:16px">190</div><div data-line-number="191" class="react-line-number react-code-text" style="padding-right:16px">191</div><div data-line-number="192" class="react-line-number react-code-text" style="padding-right:16px">192</div><div data-line-number="193" class="react-line-number react-code-text" style="padding-right:16px">193</div></div></div><div class="react-code-lines"><div><div class="react-no-virtualization-wrapper"><div id="LC1" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-c"><span class="pl-c">--</span> Netflix Data Analysis using SQL</span></div>
<div id="LC2" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-c"><span class="pl-c">--</span> Solutions of 15 business problems</span></div>
<div id="LC3" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-c"><span class="pl-c">--</span> 1. Count the number of Movies vs TV Shows</span></div>
<div id="LC4" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC5" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">SELECT</span> </div>
<div id="LC6" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">	type,</div>
<div id="LC7" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">	<span class="pl-c1">COUNT</span>(<span class="pl-k">*</span>)</div>
<div id="LC8" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">FROM</span> netflix</div>
<div id="LC9" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">GROUP BY</span> <span class="pl-c1">1</span></div>
<div id="LC10" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC11" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-c"><span class="pl-c">--</span> 2. Find the most common rating for movies and TV shows</span></div>
<div id="LC12" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC13" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">WITH RatingCounts <span class="pl-k">AS</span> (</div>
<div id="LC14" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">    <span class="pl-k">SELECT</span> </div>
<div id="LC15" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">        type,</div>
<div id="LC16" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">        rating,</div>
<div id="LC17" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">        <span class="pl-c1">COUNT</span>(<span class="pl-k">*</span>) <span class="pl-k">AS</span> rating_count</div>
<div id="LC18" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">    <span class="pl-k">FROM</span> netflix</div>
<div id="LC19" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">    <span class="pl-k">GROUP BY</span> type, rating</div>
<div id="LC20" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">),</div>
<div id="LC21" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">RankedRatings <span class="pl-k">AS</span> (</div>
<div id="LC22" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">    <span class="pl-k">SELECT</span> </div>
<div id="LC23" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">        type,</div>
<div id="LC24" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">        rating,</div>
<div id="LC25" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">        rating_count,</div>
<div id="LC26" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">        RANK() OVER (PARTITION BY type <span class="pl-k">ORDER BY</span> rating_count <span class="pl-k">DESC</span>) <span class="pl-k">AS</span> rank</div>
<div id="LC27" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">    <span class="pl-k">FROM</span> RatingCounts</div>
<div id="LC28" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">)</div>
<div id="LC29" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">SELECT</span> </div>
<div id="LC30" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">    type,</div>
<div id="LC31" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">    rating <span class="pl-k">AS</span> most_frequent_rating</div>
<div id="LC32" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">FROM</span> RankedRatings</div>
<div id="LC33" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">WHERE</span> rank <span class="pl-k">=</span> <span class="pl-c1">1</span>;</div>
<div id="LC34" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
