</div>
<div id="LC43" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-c"><span class="pl-c">--</span> 4. Find the top 5 countries with the most content on Netflix</span></div>
<div id="LC44" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC45" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">SELECT</span> <span class="pl-k">*</span> </div>
<div id="LC46" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">FROM</span></div>
<div id="LC47" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">(</div>
<div id="LC48" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">	<span class="pl-k">SELECT</span> </div>
<div id="LC49" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">		<span class="pl-c"><span class="pl-c">--</span> country,</span></div>
<div id="LC50" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">		UNNEST(STRING_TO_ARRAY(country, <span class="pl-s"><span class="pl-pds">&#39;</span>,<span class="pl-pds">&#39;</span></span>)) <span class="pl-k">as</span> country,</div>
<div id="LC51" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">		<span class="pl-c1">COUNT</span>(<span class="pl-k">*</span>) <span class="pl-k">as</span> total_content</div>
<div id="LC52" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">	<span class="pl-k">FROM</span> netflix</div>
<div id="LC53" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">	<span class="pl-k">GROUP BY</span> <span class="pl-c1">1</span></div>
<div id="LC54" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">)<span class="pl-k">as</span> t1</div>
<div id="LC55" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">WHERE</span> country <span class="pl-k">IS NOT NULL</span></div>
<div id="LC56" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">ORDER BY</span> total_content <span class="pl-k">DESC</span></div>
<div id="LC57" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">LIMIT</span> <span class="pl-c1">5</span></div>
<div id="LC58" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC59" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC60" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-c"><span class="pl-c">--</span> 5. Identify the longest movie</span></div></div>
<div class="react-no-virtualization-wrapper"><div id="LC61" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC62" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">SELECT</span> </div>
<div id="LC63" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">	<span class="pl-k">*</span></div>
<div id="LC64" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">FROM</span> netflix</div>
<div id="LC65" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">WHERE</span> type <span class="pl-k">=</span> <span class="pl-s"><span class="pl-pds">&#39;</span>Movie<span class="pl-pds">&#39;</span></span></div>
<div id="LC66" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">ORDER BY</span> SPLIT_PART(duration, <span class="pl-s"><span class="pl-pds">&#39;</span> <span class="pl-pds">&#39;</span></span>, <span class="pl-c1">1</span>)::<span class="pl-k">INT</span> <span class="pl-k">DESC</span></div>
<div id="LC67" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC68" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC69" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-c"><span class="pl-c">--</span> 6. Find content added in the last 5 years</span></div>
<div id="LC70" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">SELECT</span></div>
<div id="LC71" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">*</span></div>
<div id="LC72" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">FROM</span> netflix</div>
<div id="LC73" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">WHERE</span> TO_DATE(date_added, <span class="pl-s"><span class="pl-pds">&#39;</span>Month DD, YYYY<span class="pl-pds">&#39;</span></span>) <span class="pl-k">&gt;=</span> <span class="pl-c1">CURRENT_DATE</span> <span class="pl-k">-</span> INTERVAL <span class="pl-s"><span class="pl-pds">&#39;</span>5 years<span class="pl-pds">&#39;</span></span></div>
<div id="LC74" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC75" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC76" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-c"><span class="pl-c">--</span> 7. Find all the movies/TV shows by director &#39;Rajiv Chilaka&#39;!</span></div>
<div id="LC77" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC78" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">SELECT</span> <span class="pl-k">*</span></div>
<div id="LC79" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">FROM</span></div>
<div id="LC80" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">(</div>
<div id="LC81" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div ">
</div>
<div id="LC82" class="react-code-text react-code-line-contents-no-virtualization react-file-line html-div "><span class="pl-k">SELECT</span> </div>
